let cache: Uint8Array | null = null;

/** Decoded land mask: 1 byte per cell, 1 = land. */
export const getLandMask = (): Uint8Array => {
  if (cache) return cache;
  const bin = atob(PACKED);
  const out = new Uint8Array(MASK_W * MASK_H);
  for (let i = 0; i < out.length; i++) {
    out[i] = (bin.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;
  }
  cache = out;
  return out;
};

/** Sample land at a geographic coordinate (degrees). */
export const isLand = (mask: Uint8Array, lonDeg: number, latDeg: number): boolean => {
  const lon = ((lonDeg + 180) % 360 + 360) % 360;
  const x = Math.min(MASK_W - 1, Math.floor((lon / 360) * MASK_W));
  const y = Math.min(MASK_H - 1, Math.max(0, Math.floor(((90 - latDeg) / 180) * MASK_H)));
  return mask[y * MASK_W + x] === 1;
};
